var TODAY={"date": "2026-07-03", "dateDisplay": "2026年7月3日 星期五", "papers": [{"title": "SE(3)-LIO: SE(3)流形IMU传播+不确定性感知运动补偿 (ICRA 2026)", "venue": "ICRA 2026 — KAIST", "authors": "Gunhee Shin, Seungjae Lee, Young-Woo Seo, Hyun Myung 等 — KAIST Urban Robotics Lab", "stars": 5, "contribution": "首次将IMU传播从SO(3)+R³分离提升到SE(3)流形统一表示，旋转变化天然耦合到平移传播中；引入不确定性感知运动补偿(UAMC)，利用预测位姿协方差精确刻画相对变换不确定性。", "approach": "SE(3)流形联合位姿传播+UAMC协方差感知运动补偿+完整LiDAR-Inertial Odometry框架", "innovation": "SE(3)流形IMU传播比SO(3)+R³分离更严谨；UAMC将预测不确定性反馈到测量噪声——对丘陵剧烈姿态变化尤其关键", "recommend": "must-read", "tags": [{"text": "精读", "cls": "recommend"}, {"text": "SE(3)流形", "cls": "method"}, {"text": "IMU传播", "cls": "core"}], "url": "https://arxiv.org/abs/2603.16118"}, {"title": "GLINS: 测量级紧耦合GNSS-LiDAR-INS因子图导航系统 (RA-L 2026)", "venue": "IEEE RA-L, May 2026", "authors": "(IEEE RA-L 2026)", "stars": 5, "contribution": "测量级紧耦合原始GNSS伪距+载波相位+Doppler+IMU预积分+LiDAR路标因子统一因子图；显式路标状态使地图与全局修正协同演化，避免全局修正与静态地图冲突。含GNSS故障检测排除+载波相位模糊度解算。", "approach": "滑动窗口因子图+显式LiDAR路标状态+原始GNSS紧耦合+载波相位模糊度+故障检测", "innovation": "显式路标状态使地图随全局修正协同演化——解决了传统SLAM地图与GNSS修正冲突的问题", "recommend": "must-read", "tags": [{"text": "精读+复现", "cls": "recommend"}, {"text": "GNSS紧耦合", "cls": "core"}, {"text": "因子图", "cls": "method"}]}, {"title": "BIEVR-LIO: 凹凸图像增强体素地图的鲁棒LiDAR-Inertial里程计", "venue": "arXiv, April 2026", "authors": "(发布于2026.04)", "stars": 4, "contribution": "高分辨率地图表示将表面存储为紧凑的体素方向高度图像(Bump-Image)；提出地图信息引导的点采样策略，集中于几何信息丰富区域进行配准。", "approach": "体素方向高度图像(Bump-Image)表示+地图信息引导采样+LiDAR-Inertial紧耦合", "innovation": "Bump-Image高度图比传统体素更紧凑且保留表面细节；信息引导采样对丘陵稀疏几何特征(陡坡/沟壑)更有价值", "recommend": "must-read", "tags": [{"text": "精读", "cls": "recommend"}, {"text": "体素表示", "cls": "method"}, {"text": "地形细节", "cls": "core"}], "url": "https://arxiv.org/abs/2604.14421"}, {"title": "SOCC-ICP: 语义辅助占用网格与ICP联合LiDAR里程计 (RA-L 2026)", "venue": "IEEE RA-L, Accepted May 2026", "authors": "Johannes Scherer 等", "stars": 4, "contribution": "联合语义占用网格建图与LiDAR扫描对齐——每个体素编码几何+语义统计量，自适应ICP；光线投射自然过滤动态物体。构建的地图直接用于可通行性评估和运动规划。", "approach": "联合语义占用网格+自适应ICP+光线投射动态过滤+可通行性评估一体化", "innovation": "语义占用网格与里程计联合而非分离pipeline；地图直接可通行——减少SLAM到规划的中间层", "recommend": "must-read", "tags": [{"text": "精读", "cls": "recommend"}, {"text": "语义+几何", "cls": "method"}, {"text": "可通行性", "cls": "core"}], "url": "https://arxiv.org/abs/2605.15074"}, {"title": "AgriGS-SLAM: 果园多视图高斯泼溅跨季节SLAM (RA-L 2026)", "venue": "IEEE RA-L 2026", "authors": "Mirko Usuelli, David Rapado-Rincon, Gert Kootstra, Matteo Matteucci — Politecnico di Milano / Wageningen UR", "stars": 4, "contribution": "统一LiDAR里程计+多相机3D高斯泼溅渲染的Visual-LiDAR SLAM，在苹果/梨园跨休眠-开花-收获三季验证——首次高斯泼溅SLAM跨季节农业验证。", "approach": "LiDAR里程计+多相机3DGS渲染+回环检测+跨季节位姿图优化", "innovation": "3DGS引入农业SLAM开创性应用；跨季节鲁棒性由LiDAR几何+视觉GS互补保证", "recommend": "must-read", "tags": [{"text": "精读", "cls": "recommend"}, {"text": "Gaussian Splatting", "cls": "method"}, {"text": "农业+季节", "cls": "core"}], "url": "https://arxiv.org/abs/2510.26358"}, {"title": "CLEAR: 语义-几何地形抽象——面向长程非结构化导航", "venue": "arXiv:2601.13361, Jan 2026", "authors": "(arXiv 2026.01)", "stars": 4, "contribution": "平衡可扩展性、语义感知和几何精度的地形抽象方法，为长程非结构化环境导航设计。将地形抽象为语义+几何多层次表示，支撑大范围越野路径规划。", "approach": "语义-几何多层次地形抽象+大范围越野路径规划+长程导航验证", "innovation": "多层次地形抽象同时保留语义(植被类型/路面)和几何(坡度/粗糙度)——丘陵履带长程规划直接受益", "recommend": "must-read", "tags": [{"text": "精读", "cls": "recommend"}, {"text": "地形抽象", "cls": "method"}, {"text": "长程导航", "cls": "core"}], "url": "https://arxiv.org/abs/2601.13361"}, {"title": "TARTS: 训练无关自适应参考引导可通行性分割 (Electronics 2026)", "venue": "Electronics (MDPI), 2026, 15(6)", "authors": "(MDPI 2026)", "stars": 4, "contribution": "无需训练的One-shot DINO ViT原型初始化+轨迹引导在线自适应——零样本跨场景泛化，~94% IoU、17-24 FPS。仅需一帧参考即可分割新场景可通行区域。", "approach": "DINO ViT一次性原型初始化+轨迹引导在线自适应+无需标注训练", "innovation": "训练无关(Training-Free)——消除了可通行性标注数据瓶颈；one-shot泛化极快", "recommend": "skim", "tags": [{"text": "泛读", "cls": "venue"}, {"text": "可通行性", "cls": "core"}, {"text": "零样本", "cls": "method"}]}, {"title": "MTD-Map: 单阶段长期LiDAR地图维护——混合转移分布 (IROS 2026)", "venue": "IROS 2026 / arXiv:2606.29469 (2026.06.28)", "authors": "TaeYoung Kim 等", "stars": 3, "contribution": "混合转移分布(MTD)编码占用状态转移方向和持续时间，单阶段统一动态物体移除+变化检测，无需分离任务模块。稳定性驱动自适应策略平衡噪声抑制与准静态结构保留。", "approach": "递归MTD含高阶时序依赖+稳定性驱动自适应+单阶段动态移除+变化检测", "innovation": "MTD编码历史时序——对长期部署履带机器人(季节性植被变化/泥土堆积)有直接工程价值", "recommend": "skim", "tags": [{"text": "泛读", "cls": "venue"}, {"text": "长期部署", "cls": "method"}, {"text": "地图维护", "cls": "core"}], "url": "https://arxiv.org/abs/2606.29469"}, {"title": "ISPRS RTK-SLAM基准：大地测量级绝对精度评估 (ISPRS Congress 2026)", "venue": "ISPRS Congress 2026 — University of Stuttgart", "authors": "Wei Zhang, Vincent Ress, David Skuddis, Uwe Soergel, Norbert Haala", "stars": 4, "contribution": "首个以独立全站仪(<1cm)为真值的RTK-SLAM大地测量级基准；揭示标准SE(3)对齐ATE低估绝对误差高达76%；RTK辅助LiDAR-Inertial漂移低至8-9cm/min。公开ROS1/ROS2/EuRoC数据集。", "approach": "独立全站仪真值+RTK仅作输入+室外到室内过渡+FAST-LIO-SAM/OKVIS2-X评估", "innovation": "首次量化了标准SLAM评估指标的在绝对精度上的系统性偏差——对用户自采数据评估方法论有重要指导", "recommend": "must-read", "tags": [{"text": "精读", "cls": "recommend"}, {"text": "评估方法论", "cls": "method"}, {"text": "基准数据集", "cls": "core"}]}], "projects": [{"name": "SE(3)-LIO (KAIST Urban Robotics Lab)", "url": "https://github.com/url-kaist/se3-lio", "stars": "79⭐ (2026.06)", "highlights": "SE(3)流形IMU传播+UAMC不确定性运动补偿；ICRA 2026；ROS已开源；比传统SO(3)+R³分离更严谨；剧烈姿态变化场景受益最大", "difficulty": "★★★☆☆ 需理解SE(3)李群理论", "value": "★★★★★ 丘陵剧烈姿态场景直接可用"}, {"name": "GLIO/GLIO2 (PolyU TAS LAB GNSS-LiDAR-IMU融合)", "url": "https://github.com/polyu-taslab/glio", "stars": "学术项目 (ITSNT 2026)", "highlights": "GLIO: 因子图紧耦合GNSS/LiDAR/IMU开源源码；GLIO2: GPU并行化边缘设备版；含3D LiDAR-Aided GNSS(3DLA) NLOS检测排除+差分保护等级", "difficulty": "★★★☆☆ 依赖GTSAM+GNSS驱动", "value": "★★★★★ 与GLINS互补的GNSS紧耦合方案"}, {"name": "MTD-Map (长期LiDAR地图维护)", "url": "https://github.com/taeyoung96/mtd_map", "stars": "IROS 2026新项目", "highlights": "混合转移分布(MTD)单阶段动态移除+变化检测；SemanticKITTI/HeLiMOS/MOE验证；长期部署必备", "difficulty": "★★★☆☆ 需ROS+LiDAR", "value": "★★★★☆ 长期丘陵部署地图维护关键模块"}, {"name": "AgriGS-SLAM (农业高斯泼溅SLAM)", "url": "https://github.com/AIRLab-POLIMI/agri-gs-slam", "stars": "IEEE RA-L 2026学术配套", "highlights": "LiDAR+多相机3DGS；跨季节(休眠/开花/收获)验证；苹果/梨园真机实测", "difficulty": "★★★★☆ 多相机标定+3DGS训练", "value": "★★★★☆ 农业场景GS SLAM参考，丘陵果园可迁移"}, {"name": "TARTS (训练无关可通行性分割)", "url": "https://github.com/topics/traversability-estimation", "stars": "Electronics 2026学术配套", "highlights": "DINO ViT one-shot原型+轨迹引导在线自适应；17-24 FPS；~94% IoU；零训练零标注", "difficulty": "★★☆☆☆ 仅推理，无需训练", "value": "★★★★☆ 快速可通行性部署方案"}], "trends": [{"title": "IMU传播从SO(3)+R³分离到SE(3)统一流形——李群建模升级", "body": "SE(3)-LIO(ICRA 2026)首次将IMU传播统一到SE(3)流形，旋转变化天然耦合到位移。结合Breaking Time的GP连续时间框架和CT-VoxelMap的B样条，SLAM的位姿表示正从分离李群向统一流形+连续时间双线升级。对丘陵剧烈姿态变化场景，SE(3)统一表示比传统分离更有理论优势。"}, {"title": "GNSS紧耦合深化：从PVT→伪距/载波相位测量级", "body": "GLINS直接融合原始伪距+载波相位+Doppler测量(非PVT输出)，显式路标状态使地图与GNSS修正协同演化。结合FAST-LIVGO的Doppler/TDCP和单频GNSS虚拟锚点方案，GNSS紧耦合已从PVT级推进到原始测量级——可还原GNSS接收机丢弃的中间信息。"}, {"title": "语义占用网格与SLAM一体化——从解耦到联合", "body": "SOCC-ICP(RA-L 2026)首次将语义占用网格建图与LiDAR扫描对齐联合优化，而不是先SLAM后分割。输出的地图直接可用于可通行性评估和运动规划——消除了SLAM→规划的多层中间表示，对工程落地有直接价值。"}, {"title": "高斯泼溅SLAM从室内/城市扩展到农业/户外", "body": "AgriGS-SLAM(RA-L 2026)实现3DGS跨季节农业SLAM验证，结构化Li-GS(ISPRS 2026)以LiDAR替代SfM初始化，LIT-GS(IROS 2026)引入热红外抗光照退化。3DGS-SLAM正快速覆盖户外多场景——丘陵GS-SLAM是明确的空白机会。"}, {"title": "可通行性标注从需要训练→训练无关(Training-Free)", "body": "TARTS以DINO ViT one-shot+在线自适应实现零训练可通行性分割(~94% IoU)。与COTRATE本体感知自监督、GSAT几何自监督形成三股力量——可通行性估计正完全摆脱人工标注依赖。"}, {"title": "长期地图维护首次进入主流SLAM议程", "body": "MTD-Map(IROS 2026)以混合转移分布统一动态移除+变化检测，标志着长期部署(数周-数月)的地图维护从特定解决方案走向标准化框架。对丘陵履带平台长期自主作业(季节性植被/泥土堆积/地面侵蚀)有直接工程价值。"}], "opportunities": {"masters": [{"title": "SE(3)流形IMU传播的丘陵履带LiDAR-IMU里程计", "detail": "SE(3)-LIO的SE(3)传播迁移到履带平台，对比传统SO(3)+R³分离在丘陵剧烈姿态变化(俯仰/侧倾>20°)下的精度差异。结合Okawara在线运动学标定提供履带专属运动先验。", "meta": "SE(3) Manifold IMU Propagation with Online Kinematic Calibration for Tracked LiDAR-Inertial Odometry in Hilly Terrain"}, {"title": "SOCC-ICP语义占用网格驱动的丘陵可通行性联合SLAM", "detail": "SOCC-ICP联合优化框架+履带底盘几何约束，将占用网格编码扩展为(几何+语义+可通行性)三维一体，输出可直接用于Nav2的越野代价地图。", "meta": "Joint Semantic-Occupancy-Traversability Mapping for Tracked Platform SLAM + Navigation2 Integration"}, {"title": "MTD长期地图维护方案在丘陵履带平台的适配与验证", "detail": "MTD-Map递归时序依赖框架适配丘陵环境(季节性植被/雨后泥泞/地面侵蚀)，采集履带平台跨季节数据，量化长期部署地图退化率与MTD恢复效果。", "meta": "Adapting Mixture Transition Distribution Map Maintenance for Long-Term Tracked Robot Deployment in Hilly Environments"}], "topConference": [{"title": "GLINS显式路标+SE(3)-LIO流形传播+单频GNSS虚拟锚点→统一RMS-GNSS-LIO框架", "detail": "将GLINS的显式路标状态(地图随GNSS修正协同演化)+SE(3)流形IMU传播+单频GNSS载波相位虚拟锚点三者统一到单因子图，构建面向丘陵低成本履带的全局一致深度融合SLAM。", "meta": "目标: ICRA 2027 / IROS 2027 / IEEE RA-L"}, {"title": "SOCC-ICP+CLEAR地形抽象+COLT自监督可通行性→语义-几何-可通行性一体化SLAM", "detail": "SOCC-ICP联合SLAM+占用网格→CLEAR语义几何多层次抽象→COTRATE本体感知在线学习→统一框架输出定位+三维地形+可通行性代价场，一步到位支撑Nav2规划。", "meta": "目标: RSS 2027 / IEEE T-RO"}, {"title": "AgriGS-SLAM跨季节高斯泼溅+LiDAR几何约束→丘陵GS-SLAM", "detail": "AgriGS-SLAM跨季节3DGS框架迁移到丘陵履带场景，结构化LiD-SGS以LiDAR几何替代SfM初始化，PL-LIT热红外GS对抗光照退化——构建丘陵履带LiDAR-Inertial-Thermal GS全天候SLAM。", "meta": "目标: IROS 2027 / IEEE RA-L + ICRA 2027"}], "deployable": [{"title": "【短期 1-2月】GLIO/GLIO2 GNSS紧耦合 + SE(3)-LIO里程计 + FastDEM高程建图", "detail": "GLIO GNSS-LiDAR-IMU因子图全局定位+SE(3)-LIO局部里程计+FastDEM 100Hz高程建图。全部有开源代码，GLIO+SE(3)-LIO互补(全局+局部)，技术栈成熟。", "meta": "预计1-2月，三个开源项目都有现成ROS接口"}, {"title": "【中期 3-6月】SOCC-ICP联合语义占用+MTD长期维护+Nav2越野代价地图", "detail": "SOCC-ICP输出语义占用网格(含可通行性)→MTD-Map长期维护处理季节性变化→自定义Nav2 Costmap Plugin→Smac Hybrid-A*/MPPI越野规划", "meta": "预计3-6月，需开发SOCC-ICP到Nav2 costmap的桥接模块"}, {"title": "【长期 6-12月】GLINS测量级GNSS+SE(3)流形+SOCC语义占用+CLEAR地形抽象→完整丘陵SLAM栈", "detail": "GLINS原始GNSS伪距/载波紧耦合+SE(3)流形IMU+SOCC联合语义占用+CLEAR地形抽象+Okawara神经运动学——构建从传感器原始测量到可通行性代价场的端到端丘陵履带栈。", "meta": "预计6-12月，需大量自采数据+系统集成开发"}]}, "actions": [{"priority": "P0", "title": "精读 SE(3)-LIO，评估SE(3)流形IMU传播在丘陵履带的提升空间", "time": "1周", "type": "论文+理论"}, {"priority": "P0", "title": "精读 GLINS 测量级GNSS紧耦合因子图，对比GLIO方案", "time": "1周", "type": "论文"}, {"priority": "P0", "title": "精读 SOCC-ICP 语义占用+ICP联合框架，设计履带平台迁移方案", "time": "1周", "type": "论文+设计"}, {"priority": "P1", "title": "部署 GLIO/GLIO2 GNSS-LiDAR-IMU紧耦合在履带平台测试", "time": "1-2周", "type": "工程"}, {"priority": "P1", "title": "精读 BIEVR-LIO Bump-Image体素表示+CLEAR地形抽象", "time": "1周", "type": "论文"}, {"priority": "P1", "title": "下载 ISPRS RTK-SLAM基准数据集，建立本团队评估方法论", "time": "1周", "type": "数据+方法论"}, {"priority": "P2", "title": "研究 MTD-Map 长期地图维护，评估履带平台季节性部署需求", "time": "1周", "type": "调研"}, {"priority": "P2", "title": "探索 AgriGS-SLAM + TARTS 高斯泼溅+零样本可通行性组合", "time": "1-2周", "type": "探索"}]};
