var TODAY={"date": "2026-08-05", "dateDisplay": "2026年8月5日 星期三", "papers": [{"title": "Stipple: 实时增量式3D高斯泼溅与视觉-惯性跟踪", "venue": "arXiv:2608.00931, 2026.08 — 最新出炉", "url": "https://arxiv.org/abs/2608.00931", "authors": "学术团队 (2026.08.05发布)", "stars": 4, "contribution": "首个实现实时增量式3DGS+视觉-惯性紧耦合在线SLAM系统，高斯增删与VI位姿估计同频运行。", "approach": "增量高斯管理+VI紧耦合跟踪+在线GS添加/修剪+实时渲染", "innovation": "增量式高斯管理替代全局优化，实现真正实时在线GS-SLAM", "recommend": "must-read", "tags": [{"text": "精读", "cls": "recommend"}, {"text": "3DGS-SLAM", "cls": "method"}, {"text": "实时", "cls": "core"}]}, {"title": "Breaking Time: 全高斯框架的分布式连续时间SLAM", "venue": "IEEE RA-L / arXiv:2606.06250, 2026.06", "url": "https://github.com/rvp-group/gsolver", "authors": "Ceriola, Ferrari 等 — rvp-group (Sapienza)", "stars": 5, "contribution": "首次使用高斯置信传播(GBP)+高斯过程(GP)实现全高斯连续时间SLAM，彻底告别传统非线性最小二乘优化范式。开源代码gsolver。", "approach": "高斯置信传播(GBP)求解器+高斯过程连续轨迹+全高斯因子图", "innovation": "GBP替代GTSAM/g2o——全高斯消息传递范式突破传统优化瓶颈，天然并行", "recommend": "must-read", "tags": [{"text": "精读", "cls": "recommend"}, {"text": "GBP", "cls": "method"}, {"text": "连续时间", "cls": "core"}]}, {"title": "GenZ-LIO: 超越室内-室外边界的可泛化LiDAR-惯性里程计", "venue": "arXiv:2603.16273, 2026.03 — POSTECH", "url": "https://arxiv.org/abs/2603.16273", "authors": "Daehan Lee, Changhyeon Lee 等 — POSTECH", "stars": 4, "contribution": "GenZ-ICP配准内核+退化感知融合，单一参数配置在室内/城市/野外/隧道多场景达到SOTA，无需场景特调。", "approach": "GenZ-ICP泛化配准+分布感知点云采样+退化感知IESKF融合", "innovation": "单一模型跨场景泛化——对非结构化丘陵地形迁移潜力大", "recommend": "must-read", "tags": [{"text": "精读", "cls": "recommend"}, {"text": "泛化LIO", "cls": "core"}, {"text": "GenZ-ICP", "cls": "method"}]}, {"title": "PA-LVIO: 实时LiDAR-视觉-惯性里程计与纯位姿BA建图", "venue": "arXiv:2603.16228, 2026.03", "url": "https://arxiv.org/abs/2603.16228", "authors": "Xiaoji Niu, Hailiang Tang, Man Yuan 等 — 武汉大学", "stars": 4, "contribution": "Pose-Only Bundle Adjustment——仅优化相机位姿不优化路标点，大幅减少BA计算量，实现LiDAR-Visual-Inertial三传感器实时融合。", "approach": "纯位姿BA+LiDAR深度先验+视觉特征+IMU预积分+滑动窗口", "innovation": "Pose-Only BA是视觉BA的效率革命，适合多传感器实时融合", "recommend": "skim", "tags": [{"text": "泛读", "cls": "venue"}, {"text": "L-VIO", "cls": "core"}, {"text": "纯位姿BA", "cls": "method"}]}, {"title": "R-VoxelMap: 递归平面拟合的高精度体素建图在线LiDAR里程计", "venue": "IEEE RA-L / arXiv:2601.12377, 2026.01", "url": "https://arxiv.org/abs/2601.12377", "authors": "Xi, Zhang 等", "stars": 4, "contribution": "递归平面拟合替代逐点最近邻，体素内递归合并共面点→平面参数持续精化，建图精度超越CT-ICP和KISS-ICP。", "approach": "递归平面拟合+增量体素平面更新+自适应体素尺寸+LiDAR里程计", "innovation": "递归平面拟合利用体素内空间连续性，噪声抑制优于逐点方法", "recommend": "skim", "tags": [{"text": "泛读", "cls": "venue"}, {"text": "体素建图", "cls": "method"}, {"text": "平面拟合", "cls": "core"}]}], "projects": [{"name": "GenZ-ICP (可泛化ICP配准内核)", "url": "https://github.com/cocel-postech/genz-icp", "stars": "POSTECH — 活跃开发", "highlights": "GenZ-LIO核心配准模块；分布感知点云采样；单一配置跨场景泛化；可嵌入任意LIO框架", "difficulty": "★★★☆☆ C++，模块化设计", "value": "★★★★★ 泛化ICP作为drop-in替换，大幅提升现有LIO框架的跨场景鲁棒性"}], "trends": [{"title": "LiDAR Gaussian Splatting SLAM从概念验证走向实时几何融合", "body": "Stipple(2608.00931)的增量在线GS、Geometry-Aware LiDAR-GS(2607.04127)的协方差耦合、Structured-Li-GS(2606.27509)的LiDAR空间约束——三者共同标志着LiDAR+GS SLAM从离线渲染走向实时几何稠密建图。核心突破是LiDAR几何不确定性显式建模进入GS优化，解决了纯RGB高斯在弱纹理/植被遮挡场景的脆弱性。对丘陵山地稠密建图和可视化有直接价值。"}, {"title": "全高斯SLAM范式浮现——GBP+GP挑战传统非线性优化", "body": "Breaking Time(2606.06250)首次用高斯置信传播+高斯过程完全替代GTSAM/g2o，全高斯消息传递天然支持并行化和分布式部署。这不仅是工程加速，更是SLAM后端基础范式的潜在变革——如果GBP的精度-效率权衡持续优化，未来SLAM后端可能从因子图优化转向概率消息传递。"}, {"title": "跨场景泛化SLAM成为关键命题——告别场景特调", "body": "GenZ-LIO(2603.16273)的单一配置跨场景SOTA性能、Robust urban SLAM (ISPRS)的五源韧性切换策略共同推动SLAM从每个场景一套参数向一次部署到处运行演进。这对履带平台在丘陵/城市/隧道/开阔地之间的场景切换至关重要。"}, {"title": "图论方法进入地点识别——团搜索替代描述子距离", "body": "GLoC(ISPRS 2026)将图论团搜索引入LiDAR地点识别，与DTIF的Delaunay拓扑回环(2607.21138)形成方法论双峰。两者都采用图/拓扑结构替代传统描述子，对丘陵植被遮挡场景的鲁棒性提升是共同优势。图论+拓扑的回环检测正在成为新范式。"}, {"title": "Pose-Only BA和递归平面拟合——追求极致效率的SLAM前端", "body": "PA-LVIO(2603.16228)的纯位姿BA将视觉优化从O(N+M)降至O(N)，R-VoxelMap(2601.12377)的递归平面拟合实现建图精度与速度双赢。两类方法都聚焦在不动后端架构的前提下通过前端效率革命实现实时性提升——这对多传感器融合系统的实时性瓶颈有直接借鉴。"}], "opportunities": {"masters": [{"title": "GenZ-LIO泛化配准迁移到履带平台丘陵场景验证", "detail": "GenZ-LIO的GenZ-ICP泛化配准已在室内/城市/野外/隧道验证，但其分布感知采样策略对丘陵的特殊地形(沟壑、植被、岩石)适用性尚未评估。直接迁移到履带平台+丘陵数据集，对比FAST-LIO2的配准精度和鲁棒性。工作量适中(1-2月)，结果明确。", "meta": "GenZ-LIO Transfer to Tracked Platform in Hilly Terrain — 跨场景泛化配准的丘陵适用性评估"}, {"title": "图论团搜索(GLoT)回环检测在丘陵植被遮挡场景的适配", "detail": "GLoC的全局-局部图融合+最大团搜索匹配对植被遮挡天然鲁棒，结合DTIF拓扑不变思想，设计丘陵履带平台的混合图论回环检测方案：GLoC图匹配提供回环候选+DTIF拓扑约束过滤假阳性。在M3DGR越野数据集或自采履带数据上验证。", "meta": "Graph-Theoretic Loop Closure: GLoC + DTIF Hybrid for Tracked Robots in Hilly Vegetation"}, {"title": "VoxelNav语义体素可通行性+履带平台嵌入式部署", "detail": "VoxelNav的实时语义体素建图(100ms/Jetson Nano)+履带平台运动学约束→构建语义-几何联合可通行性图层。评估在Jetson Orin上的实时性能和可通行性预测准确率。直接可出实验论文+工程演示。", "meta": "Embedded Semantic Voxel Traversability Mapping for Tracked Skid-Steer Robots"}], "topConference": [{"title": "连续时间GBP-GP框架的履带多传感器融合SLAM", "detail": "Breaking Time的全高斯GBP-GP框架天然适合异频传感器(LiDAR 10Hz+IMU 200Hz+RTK 1Hz+轮速50Hz)的连续时间融合。加入履带运动学因子(Okawara在线标定)，构建首个GBP框架下的履带平台多传感器紧耦合SLAM。开拓GBP多传感器融合新方向+履带运动学约束双创新。", "meta": "目标: RSS 2027 / IEEE T-RO — 全高斯连续时间+履带运动学融合"}, {"title": "LiDAR几何感知3DGS的丘陵稠密可通行性建图", "detail": "Geometry-Aware LiDAR-GS(2607.04127)的协方差耦合+Structured-Li-GS空间约束+FastDEM高程→构建几何不确定性感知的GS稠密可通行性地图。关键创新：3DGS的协方差直接编码地形不确定性和可通行性——一个高斯既描述几何又描述安全。", "meta": "目标: ICRA 2027 / IEEE RA-L — LiDAR-GS协方差驱动的可通行性表征"}, {"title": "图论+拓扑混合回环检测的履带越野SLAM", "detail": "GLoC图匹配+DTIF拓扑约束+WinTA-GIL GNSS间歇航向恢复→三合一回环检测框架。图匹配提供全局一致性，拓扑约束过滤假阳性，GNSS航向提供验证。对丘陵植被密集、GNSS间歇的场景构成完整回环方案。", "meta": "目标: IROS 2027 — 图论+拓扑+GNSS的三层回环检测架构"}], "deployable": [{"title": "【短期 1-2周】plain_slam_ros2 + GenZ-ICP 快速基线部署", "detail": "plain_slam_ros2作为极简LIO框架+GenZ-ICP作为drop-in配准替换→履带平台快速原型。评估GenZ-ICP在丘陵场景的配准精度vs标准ICP/NDT。", "meta": "预计1-2周，代码量极小，快速出对比结果"}, {"title": "【中期 3-6月】VoxelNav语义体素可通行性+Nav2集成", "detail": "VoxelNav语义体素建图→可通行性语义图层→自定义Nav2 Costmap Plugin→Smac Hybrid-A*/MPPI规划。重点评估在Jetson嵌入式平台上的实时性(目标<200ms端到端)。", "meta": "预计3-6月，需开发Nav2 costmap plugin+嵌入式优化"}, {"title": "【长期 6-12月】LiDAR-GS协方差可通行性+GBP融合后端履带全栈", "detail": "Geometry-Aware LiDAR-GS前端(稠密建图+可通行性)+Breaking Time GBP后端(连续时间融合)+VoxelNav语义增强+Nav2规划→完整履带平台感知-规划-控制系统。", "meta": "预计6-12月，需要GPU+嵌入式优化+大量野外实验"}]}, "actions": [{"priority": "P0", "title": "精读 Breaking Time (GBP-GP连续时间SLAM)，评估在履带异频融合中的方法论迁移", "time": "1-2周", "type": "论文"}, {"priority": "P0", "title": "精读 Geometry-Aware LiDAR-GS SLAM (2607.04127)，理解协方差耦合机制", "time": "1周", "type": "论文"}, {"priority": "P0", "title": "部署 plain_slam_ros2 + GenZ-ICP 到履带平台，完成快速基线评估", "time": "1-2周", "type": "工程"}, {"priority": "P1", "title": "精读 GLoC 图论地点识别 + Robust urban SLAM五源融合，设计丘陵回环+融合方案", "time": "1周", "type": "论文"}, {"priority": "P1", "title": "精读 GenZ-LIO，评估GenZ-ICP在丘陵场景的泛化配准精度", "time": "1周", "type": "论文+实验"}, {"priority": "P2", "title": "评估 VoxelNav 嵌入式语义体素建图在Jetson Orin上的实时性能", "time": "2-3天", "type": "工程探索"}, {"priority": "P2", "title": "泛读 Stipple + Structured-Li-GS，跟踪LiDAR-GS-SLAM前沿", "time": "3天", "type": "论文"}]};
